import React, { useState, useEffect, useCallback } from "react";
import {
  Box,
  Typography,
  IconButton,
  Tooltip,
  alpha,
  useTheme,
} from "@mui/material";
import {
  Visibility as ViewIcon,
  Reply as ReplyIcon,
  Person as PersonIcon,
} from "@mui/icons-material";
import DataTable from "../../../components/DataTable";
import DetailsModal from "../../../components/DetailsModal";
import { useSelector } from "react-redux";
import { toast } from "react-hot-toast";
import { mapFeedbackExport } from "../../../utils/exportMappers";
import { extractExportList, performExport } from "../../../utils/exportHelpers";
import dayjs from "dayjs";

const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const truncate = (str, n = 15) => {
  if (!str) return "-";
  return str.length > n ? str.substr(0, n) + "..." : str;
};

// Dummy Data Removed - Now using API

const ContactMessages = () => {
  const theme = useTheme();
  const [messages, setMessages] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(0); // MUI 0-indexed
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [orderBy, setOrderBy] = useState("created_at");
  const [order, setOrder] = useState("desc");
  const [searchTerm, setSearchTerm] = useState("");
  const [isExporting, setIsExporting] = useState(false);

  const [openViewModal, setOpenViewModal] = useState(false);
  const [selectedMessage, setSelectedMessage] = useState(null);

  const token = useSelector((state) => state.auth.token);

  const fetchMessages = useCallback(
    async (apiPage, limit) => {
      if (!token) return;
      setIsLoading(true);
      try {
        const queryParams = new URLSearchParams({
          page: apiPage,
          limit: limit,
          sort_by: orderBy,
          sort_order: order,
          q: searchTerm,
        });

        const res = await fetch(`${BASE_URL}/contacts?${queryParams.toString()}`, {
          method: "GET",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        });
        const json = await res.json();
        if (!res.ok || json.error) {
          toast.error(json.message || "Failed to fetch feedback");
          return;
        }
        setMessages(json.data.contacts || []);
        setTotalCount(json.data.pagination?.total || 0);
      } catch (err) {
        console.error("Error fetching messages:", err);
        toast.error("Something went wrong while fetching feedback");
      } finally {
        setIsLoading(false);
      }
    },
    [token, orderBy, order, searchTerm],
  );

  useEffect(() => {
    if (token) {
      fetchMessages(page + 1, rowsPerPage);
    }
  }, [page, rowsPerPage, fetchMessages, token]);

  const handleSortChange = (property) => {
    const isAsc = orderBy === property && order === "asc";
    setOrder(isAsc ? "desc" : "asc");
    setOrderBy(property);
    setPage(0);
  };

  const handleViewDetails = (message) => {
    setSelectedMessage(message);
    setOpenViewModal(true);
  };

  const handleRespond = (message) => {
    const subject = encodeURIComponent(`Re: Inquiry from ${message.name}`);
    const mailtoUrl = `mailto:${message.email}?subject=${subject}`;
    window.open(mailtoUrl, "_blank");
    toast.success("Opening email composer...");
  };

  const handleExportMessages = useCallback(async (dates, format) => {
    if (!token) return;
    const toastId = toast.loading(`Exporting messages as ${format.toUpperCase()}...`);
    setIsExporting(true);
    try {
      const queryParams = new URLSearchParams({
        q: searchTerm,
        sort_by: orderBy,
        sort_order: order,
        not_pagination: "true",
        start_date: dates.startDate.format('YYYY-MM-DD'),
        end_date: dates.endDate.format('YYYY-MM-DD'),
      });

      const res = await fetch(`${BASE_URL}/contacts?${queryParams.toString()}`, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(json.message || "Failed to fetch messages for export");
      }

      const items = extractExportList(json, 'contacts');
      const filename = `Feedback_${dates.startDate.format('YYYYMMDD')}_to_${dates.endDate.format('YYYYMMDD')}`;

      await performExport({
        items,
        mapper: mapFeedbackExport,
        format,
        filename,
        sheetName: 'Feedback',
        entityName: 'messages',
        toastId,
      });
    } catch (err) {
      console.error("Export error:", err);
      toast.error(err.message || "Something went wrong while exporting", { id: toastId });
    } finally {
      setIsExporting(false);
    }
  }, [token, searchTerm, orderBy, order]);

  const columns = [
    {
      id: "name",
      label: "Sender",
      sortable: true,
      render: (row) => (
        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          <Box
            sx={{
              width: 36,
              height: 36,
              borderRadius: "10px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              bgcolor: alpha(theme.palette.primary.main, 0.1),
              color: theme.palette.primary.main,
            }}
          >
            <PersonIcon sx={{ fontSize: 20 }} />
          </Box>
          <Box>
            <Typography
              sx={{ color: "#FFFFFF", fontWeight: 600, fontSize: "0.875rem" }}
            >
              {row.name}
            </Typography>
            <Typography variant="caption" sx={{ color: "#8B8D97" }}>
              {row.email}
            </Typography>
          </Box>
        </Box>
      ),
    },
    {
      id: "query",
      label: "Message",
      sortable: false,
      render: (row) => (
        <Typography sx={{ color: "#FFFFFF", fontSize: "0.875rem" }}>
          {truncate(row.query, 15)}
        </Typography>
      ),
    },
    {
      id: "created_at",
      label: "Date Received",
      sortable: true,
      render: (row) => (
        <Typography sx={{ color: "#8B8D97", fontSize: "0.875rem" }}>
          {row.created_at
            ? new Date(row.created_at).toLocaleDateString("en-US", {
                month: "short",
                day: "numeric",
                year: "numeric",
                hour: "2-digit",
                minute: "2-digit",
              })
            : "-"}
        </Typography>
      ),
    },
    {
      id: "actions",
      label: "Actions",
      render: (row) => (
        <Box sx={{ display: "flex", gap: 1 }}>
          <Tooltip title="View Full Message">
            <IconButton
              size="small"
              onClick={() => handleViewDetails(row)}
              sx={{
                color: "#9F6EDA",
                bgcolor: alpha("#9F6EDA", 0.1),
                "&:hover": { bgcolor: alpha("#9F6EDA", 0.2) },
              }}
            >
              <ViewIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          <Tooltip title="Respond">
            <IconButton
              size="small"
              onClick={() => handleRespond(row)}
              sx={{
                color: "#9F6EDA",
                bgcolor: alpha("#9F6EDA", 0.1),
                "&:hover": { bgcolor: alpha("#9F6EDA", 0.2) },
              }}
            >
              <ReplyIcon fontSize="small" />
            </IconButton>
          </Tooltip>
        </Box>
      ),
    },
  ];

  const messageDetailsData = React.useMemo(() => {
    if (!selectedMessage) return [];
    return [
      { label: "Sender Name", value: selectedMessage.name },
      { label: "Email Address", value: selectedMessage.email },
      {
        label: "Full Message",
        value: selectedMessage.query || "No message content",
        vertical: true,
      },
      {
        label: "Date Received",
        value: selectedMessage.created_at
          ? new Date(selectedMessage.created_at).toLocaleString()
          : "N/A",
      },
    ];
  }, [selectedMessage]);

  return (
    <Box sx={{ p: { xs: 1, md: 3 } }}>
      <DataTable
        title="feedback"
        columns={columns}
        data={messages}
        isLoading={isLoading}
        searchTerm={searchTerm}
        onSearchChange={(val) => {
          setSearchTerm(val);
          setPage(0);
        }}
        onExport={handleExportMessages}
        isExporting={isExporting}
        orderBy={orderBy}
        order={order}
        onSortChange={handleSortChange}
        pagination={{
          page: page,
          rowsPerPage: rowsPerPage,
          totalCount: totalCount,
          onPageChange: (_, newPage) => setPage(newPage),
          onRowsPerPageChange: (e) => {
            setRowsPerPage(parseInt(e.target.value, 10));
            setPage(0);
          },
        }}
        emptyTitle="No messages found"
        emptyMessage="You have zero contact inquiries at the moment."
      />

      {selectedMessage && (
        <DetailsModal
          open={openViewModal}
          onClose={() => setOpenViewModal(false)}
          title="Message Details"
          data={messageDetailsData}
          maxWidth="sm"
        >
          {/* Additional styling for the message body could go here if needed, but the DetailsModal already handles vertical values neatly */}
        </DetailsModal>
      )}
    </Box>
  );
};

export default ContactMessages;
